{
  "protocolRevision": "2026-07-28",
  "serverInfo": {
    "name": "io.example.demo/forecasts",
    "title": "Forecasts",
    "version": "1.4.0",
    "description": "Synthetic demo server for forecasts."
  },
  "capabilities": {
    "tools": {
      "listChanged": false
    },
    "resources": {},
    "prompts": {}
  },
  "tools": [
    {
      "name": "get_forecast",
      "title": "Get forecast",
      "description": "Returns a synthetic forecast for a region.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "region": {
            "type": "string"
          }
        },
        "required": [
          "region"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "_meta": {
        "io.example.demo/cost": "free"
      },
      "execution": {
        "taskSupport": "optional"
      }
    }
  ],
  "resources": [
    {
      "name": "regions",
      "uri": "https://forecasts.example.test/regions",
      "mimeType": "application/json"
    }
  ],
  "prompts": [
    {
      "name": "summarize_week",
      "title": "Summarize the week",
      "arguments": [
        {
          "name": "region",
          "required": true
        }
      ]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://forecasts.example.test/mcp",
      "headers": [
        {
          "name": "Authorization",
          "isSecret": true,
          "isRequired": true,
          "description": "Supplied by the client."
        }
      ]
    }
  ],
  "_meta": {
    "io.example.demo/build": "synthetic"
  }
}
